{
  "fgos-session-register": {
    "enabled": true,
    "SessionStart": [
      {
        "type": "command",
        "command": "'<ROOT>/.fgos/installation/bin/fgos' identity session --register >/dev/null || true",
        "timeout": 10
      }
    ]
  },
  "fgos-dispatch-guard": {
    "enabled": true,
    "PreToolUse": [
      {
        "matcher": ".*",
        "hooks": [
          {
            "type": "command",
            "command": "'<ROOT>/.fgos/installation/bin/fgos' hook dispatch-decide --format=agy",
            "timeout": 10
          }
        ]
      }
    ]
  },
  "fgos-decision-guard": {
    "enabled": true,
    "PreToolUse": [
      {
        "matcher": "ask.*|AskUserQuestion",
        "hooks": [
          {
            "type": "command",
            "command": "'<ROOT>/.fgos/installation/bin/fgos' hook decision-question --format=agy",
            "timeout": 10
          }
        ]
      }
    ]
  },
  "fgos-delete-guard": {
    "enabled": true,
    "PreToolUse": [
      {
        "matcher": "run_command",
        "hooks": [
